function drawShip() {
  // Draw a simple triangular ship with gradient and glow
  const grad = ctx.createLinearGradient(ship.x, ship.y, ship.x, ship.y + ship.h);
  grad.addColorStop(0, '#00ff80');
  grad.addColorStop(1, '#006640');
  ctx.fillStyle = grad;
