  ctx.shadowBlur = 12;
  ctx.shadowColor = '#00ff80';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w / 2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();
  // Reset shadow for other drawings
  ctx.shadowBlur = 0;
}

